Object.assign($.easing, {
  ballisticUp(x, t, b, c, d) {
    return -3 * x * x + 4 * x;
  },
  ballisticDown(x, t, b, c, d) {
    x = 1 - x;
    return 1 - (-3 * x * x + 4 * x);
  },
  quadUp(x, t, b, c, d) {
    x = 1 - x;
    return 1 - x * x;
  },
  quadDown(x, t, b, c, d) {
    return x * x;
  }
});
