  shelltrap: {
    anim(scene, [attacker, ...defenders]) {
      for (const defender2 of defenders) {
        defender2.delay(280);
        defender2.anim({
          z: defender2.behind(20),
          time: 100
        }, "swing");
        defender2.anim({
          time: 300
        }, "swing");
      }
      const defender = defenders[1] || defenders[0];
      let xf = [1, -1, 1, -1];
      let yf = [1, -1, -1, 1];
      let xf2 = [1, 0, -1, 0];
      let yf2 = [0, 1, 0, -1];
      scene.backgroundEffect("#000000", 600, 0.3);
      for (let i = 0; i < 4; i++) {
        scene.showEffect("flareball", {
          x: attacker.x,
          y: attacker.y,
          z: attacker.behind(-5),
          scale: 0.5,
          opacity: 1
        }, {
          x: defender.x + 240 * xf[i],
          y: defender.y,
          z: defender.z + 137 * yf[i],
          opacity: 0,
          time: 600
        }, "decel");
        scene.showEffect("flareball", {
          x: attacker.x,
          y: attacker.y,
          z: attacker.behind(-5),
          scale: 0.5,
          opacity: 1
        }, {
          x: defender.x + 339 * xf2[i],
          y: defender.y + 10,
          z: defender.z + 194 * yf2[i],
          scale: 1,
          opacity: 0,
          time: 600
        }, "decel");
      }
      scene.showEffect("fireball", {
        x: attacker.x,
        y: attacker.y,
        z: attacker.z,
        scale: 1,
        opacity: 0.7
      }, {
        x: defender.x,
        y: defender.y,
        z: defender.z,
        scale: 1.5,
        opacity: 0.6,
        time: 300
      }, "linear", "explode");
    },
    prepareAnim: BattleOtherAnims.chargestatus.anim
  },
